import csv,hashlib,math,json
from pathlib import Path
p=Path(__file__).resolve().parent;src=p.parents[1]/'evidence'/'ALL12_FI_FFS_CONTRAST_RECOMPUTED.tsv'
with src.open() as f: rows=list(csv.DictReader(f,delimiter='\t'))
assert len(rows)==12 and len({r['sleep_trait'] for r in rows})==12
pv=[float(r['p']) for r in rows]+[1.0]*384;order=sorted(range(len(pv)),key=pv.__getitem__);q=[0.]*len(pv);best=1.
for rank in range(len(pv),0,-1):
 i=order[rank-1];best=min(best,pv[i]*len(pv)/rank);q[i]=best
names={'insomnia':'Insomnia','sleepdur':'Sleep duration','shortsleep':'Short sleep','longsleep':'Long sleep','chronotype':'Chronotype','sleepiness':'Daytime sleepiness','napping':'Napping','snoring':'Snoring','sleep_apnea':'Sleep apnea','sleep_efficiency':'Sleep efficiency','accel_sleep_duration':'Accelerometer sleep duration','sleep_timing':'Sleep timing'}
lines=['# FI and FFS: paired genetic correlations across 12 sleep traits','','These are post-hoc comparisons of archived LDSC estimates, with FI and FFS matched to each sleep trait on the same SNP support and 200 jackknife blocks. Each row uses its own support and phenotype sources; the rows are not an independent cohort or a direct comparison among sleep traits. The difference is **FFS minus FI**. The confidence intervals are nominal 95% intervals, not multiplicity-adjusted.','', '| Sleep trait | FI r_g (SE) | FFS r_g (SE) | Difference (95% CI) | Raw p | Padded BH q396 |','|---|---:|---:|---:|---:|---:|']
for i,r in enumerate(rows):
 a,b,delta,se,low,high=[float(r[x]) for x in ('FI_rg','FFS_rg','estimate','SE','lower95','upper95')];pval=float(r['p']);assert abs(delta-(b-a))<1e-12 and abs(math.erfc(abs(delta/se)/math.sqrt(2))-pval)<1e-12;assert abs(q[i]-float(r['BH_q396']))<1e-12;assert r['aligned_blocks']=='200' and r['all_separators_equal']=='True' and r['h2_gate_pass']=='True'
 lines.append(f"| {names[r['sleep_trait']]} | {a:.3f} ({float(r['FI_SE']):.3f}) | {b:.3f} ({float(r['FFS_SE']):.3f}) | {delta:+.3f} [{low:+.3f}, {high:+.3f}] | {pval:.3g} | {q[i]:.3g} |")
lines += ['', 'Only insomnia crosses both the archived padded-family BH and Bonferroni thresholds of 0.05. Snoring has raw p=0.00273 but padded BH q=0.540, so it is not a corrected difference. Non-significant contrasts do not establish equal genetic correlations. The q-values apply to **differences**, not to tests that either individual correlation is nonzero. The archived correction used the 12 observed p-values plus 384 p=1 placeholders, not 396 observed contrast tests; it is a conservative padded family, not a joint FDR over all exploratory analyses.','', 'FI includes insomnia and tiredness, and FFS includes exhaustion; overlapping UK Biobank participants and different constructs remain relevant. These are genetic correlations, not phenotypic correlations, estimates of causal effects or item-excluded analyses. HFRS is not included in this particular twelve-trait comparison; the [three-frailty insomnia sensitivity](../../global_audit/brain6_frailty_covariance/three_frailty_common_support/RESULTS.md) uses a different shared support.','', 'The [source table](../../evidence/ALL12_FI_FFS_CONTRAST_RECOMPUTED.tsv), [global audit](../../global_audit/GLOBAL_RECHECK.md), [paired comparison context](../FRAILTY_COMPARISON.md) and [script](build.py) preserve the input and arithmetic. Verification recalculates the difference, normal-tail p-values and padded BH values from the stored results; it does not independently rerun LDSC or validate cohort overlap and phenotypes.']
(p/'RESULTS.md').write_text('\n'.join(lines)+'\n');receipt={'source_sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'rows':len(rows),'padded_family':396,'placeholders':384,'p_and_bh_recomputed':True,'all_aligned_blocks':200,'all_source_h2_gates_passed':True,'note':'Arithmetic review of saved sensitivity estimates, not an independent LDSC rerun.'};(p/'receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt,indent=2))
